	{
		name = "CeroCharge.Gather", -- CeroCharge: Red lines sucked into the palm
		offset = Vector3.new(2.4, 4.3, 0),
		rotation = Vector3.new(0, 0, 0), -- degrees, CFrame.Angles order
		partSize = Vector3.new(14, 14, 14),
		emits = {  },
		rate = { {0, 0.7, 90} },
		props = {
			Texture = TEXTURES.line,
			Shape = Enum.ParticleEmitterShape.Sphere,
			ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface,
			ShapeInOut = Enum.ParticleEmitterShapeInOut.Inward,
			Speed = NumberRange.new(30, 40),
			Lifetime = NumberRange.new(0.2, 0.22),
			Orientation = Enum.ParticleOrientation.VelocityParallel,
			Size = NS({ {0, 0}, {0.3, 4, 1}, {1, 1} }),
			Color = CS({ {0, "#ff4058"}, {1, "#ffe0e4"} }),
			LightEmission = 1,
